package database

// The sqlcgen subpackage contains only code generated by sqlc (ADR-0014) from the queries in
// backend/queries/ and the schema in backend/migrations/, configured by backend/sqlc.yaml. Never
// edit it by hand: change the SQL or the configuration, then regenerate from backend/:
//
//	go generate ./internal/database/...
//
// The sqlc version is locked in tools/go.mod, like oapi-codegen. sqlc is built without cgo (it
// parses SQL with a WebAssembly build of the PostgreSQL parser), so the command runs unchanged on
// Linux, macOS and Windows. CI regenerates the package and fails if the result differs.

//go:generate go tool -modfile=../../tools/go.mod sqlc generate -f ../../sqlc.yaml
